def build_prompt(system, examples, user_input):
    parts = [f"[SYSTEM]\n{system}\n"]
    for i, (q, a) in enumerate(examples, 1):
        parts.append(f"[EXAMPLE {i}]\nUser: {q}\nAssistant: {a}\n")
    parts.append(f"[USER]\n{user_input}\n[ASSISTANT]")
    return "\n".join(parts)

system = "You are a concise technical assistant. Reply in one sentence."
examples = [
    ("What is a list?", "A list is an ordered, mutable collection of items."),
    ("What is a dict?", "A dict maps unique keys to values using a hash table."),
]
user_input = "What is a tuple?"
prompt = build_prompt(system, examples, user_input)
for line in prompt.split("\n"):
    print(line)
